`timescale 1ns/1ps
import hmao_pkg::*;

module tb_hmao_collision_real_data;

  localparam int unsigned NUM_ZON = 50;
  localparam int unsigned NUM_GEN = 16;
  localparam int unsigned MAX_OBS = 1;
  localparam real CLK_PERIOD_NS = 2.5;

  logic clk = 1'b0;
  logic rst_n = 1'b0;
  always #(CLK_PERIOD_NS / 2.0) clk = ~clk;

  task automatic do_reset(int cycles = 6);
    rst_n = 1'b0;
    repeat (cycles) @(posedge clk);
    @(negedge clk); rst_n = 1'b1;
  endtask

  logic start = 1'b0;
  logic [NUM_ZON*128-1:0] zonotopes_in;
  logic [31:0] bbox_xmin, bbox_xmax, bbox_ymin, bbox_ymax;
  logic no_collision;
  logic potential_coll;
  logic [MAX_SUSPICIOUS_OBS*16-1:0] suspicious_ids;
  logic [63:0] violation_info;
  logic overflow_err;

  axi4_ro_if #(.ADDR_W(32), .DATA_W(256)) axi_if(.aclk(clk), .aresetn(rst_n));

  hmao_collision_sat #(
    .NUM_ZONOTOPES  (NUM_ZON),
    .NUM_GENERATORS (NUM_GEN),
    .MAX_OBSTACLES  (MAX_OBS)
  ) u_dut (
    .clk            (clk),
    .rst_n          (rst_n),
    .start          (start),
    .zonotopes_in   (zonotopes_in),
    .axi_ro         (axi_if),
    .bbox_xmin      (bbox_xmin),
    .bbox_xmax      (bbox_xmax),
    .bbox_ymin      (bbox_ymin),
    .bbox_ymax      (bbox_ymax),
    .no_collision   (no_collision),
    .potential_coll (potential_coll),
    .suspicious_ids (suspicious_ids),
    .violation_info (violation_info),
    .overflow_err   (overflow_err)
  );

  logic [255:0] obs_beat0;
  logic [255:0] obs_beat1;

  typedef enum logic [1:0] { SL_IDLE, SL_AR_ACK, SL_BEAT1, SL_BEAT2 } sl_state_t;
  sl_state_t sl_state;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      axi_if.arready <= 1'b0; axi_if.rvalid <= 1'b0;
      axi_if.rdata <= '0; axi_if.rlast <= 1'b0; sl_state <= SL_IDLE;
    end else begin
      unique case (sl_state)
        SL_IDLE: begin
          axi_if.arready <= 1'b0; axi_if.rvalid <= 1'b0; axi_if.rlast <= 1'b0;
          if (axi_if.arvalid) sl_state <= SL_AR_ACK;
        end
        SL_AR_ACK: begin
          axi_if.arready <= 1'b1; axi_if.rvalid <= 1'b0; sl_state <= SL_BEAT1;
        end
        SL_BEAT1: begin
          axi_if.arready <= 1'b0; axi_if.rvalid <= 1'b1; axi_if.rlast <= 1'b0;
          axi_if.rdata <= obs_beat0;
          if (axi_if.rready) sl_state <= SL_BEAT2;
        end
        SL_BEAT2: begin
          axi_if.rvalid <= 1'b1; axi_if.rlast <= 1'b1; axi_if.rdata <= obs_beat1;
          if (axi_if.rready) begin
            axi_if.rvalid <= 1'b0; axi_if.rlast <= 1'b0; sl_state <= SL_IDLE;
          end
        end
        default: sl_state <= SL_IDLE;
      endcase
    end
  end

  task automatic pack_obstacle(
    input logic [31:0] pos_x_q, pos_y_q, dim_w_q, dim_l_q,
    input logic [7:0]  conf_val, class_val
  );
    obs_beat0 = { dim_w_q, dim_l_q, 32'h0, 32'h0, 32'h0, 32'h0, pos_y_q, pos_x_q };
    obs_beat1 = { 160'h0, conf_val, class_val, 16'h0042, 32'h0, 32'h0 };
  endtask

  task automatic load_zonotopes(
    input logic [15:0] cx_arr[NUM_ZON], cy_arr[NUM_ZON],
    input logic [15:0] g1x_arr[NUM_ZON], g1y_arr[NUM_ZON],
    input logic [15:0] g2x_arr[NUM_ZON], g2y_arr[NUM_ZON]
  );
    for (int i = 0; i < NUM_ZON; i++) begin
      zonotopes_in[i*128+112 +: 16] = cx_arr[i];
      zonotopes_in[i*128+96  +: 16] = cy_arr[i];
      zonotopes_in[i*128+80  +: 16] = g1x_arr[i];
      zonotopes_in[i*128+64  +: 16] = g1y_arr[i];
      zonotopes_in[i*128+48  +: 16] = g2x_arr[i];
      zonotopes_in[i*128+32  +: 16] = g2y_arr[i];
      zonotopes_in[i*128+16  +: 16] = 16'h0;
      zonotopes_in[i*128+0   +: 16] = 16'h0;
    end
  endtask

  task automatic wait_for_result(output int unsigned elapsed, input int unsigned timeout = 5000);
    elapsed = 0;
    while (!no_collision && !potential_coll) begin
      @(posedge clk); elapsed++;
      if (elapsed >= timeout) begin $display("  [TIMEOUT]"); break; end
    end
    elapsed++;
  endtask

  task automatic pulse_start();
    @(negedge clk); start = 1'b1;
    @(negedge clk); start = 1'b0;
  endtask

  int unsigned pass_cnt = 0;
  int unsigned fail_cnt = 0;

  task automatic chk(input string label, input logic got, input logic exp);
    if (got === exp) begin $display("  PASS | %s  got=%b exp=%b", label, got, exp); pass_cnt++; end
    else begin $display("  FAIL | %s  got=%b exp=%b", label, got, exp); fail_cnt++; end
  endtask

